const CONTRACTS_TOOLS_INLINE: { tool: string; purpose: string }[] = [
  { tool: 'create_contract', purpose: 'Create a contract in the Draft stage from a contract type and a counterparty, with its term, effective and end dates, renewal settings, and optional amount. Input fields depend on each other, so follow the rules in the tool guidance.' },
  { tool: 'create_contract_with_document_fields', purpose: 'Create a contract using the regular contract field inputs and values for fields embedded in its document template. This endpoint uses externalSource instead of source. Custom document date values must be supplied as Unix timestamps in milliseconds. Uploaded templates require the ZohoWriter.documentEditor.ALL OAuth scope.' },
  { tool: 'create_counterparty', purpose: 'Create an external organization as a counterparty, with its type and optional address, website, jurisdiction, time zone, and contact details.' },
  { tool: 'create_counterparty_type', purpose: 'Create a counterparty type by name and retrieve its server-generated API name.' },
  { tool: 'create_department', purpose: 'Create a department by name and retrieve its server-generated API name.' },
  { tool: 'create_obligation', purpose: 'Create a new obligation in a contract. The obligation can be a simple note (hasTask=false) or a task-based obligation (hasTask=true) that is either one-time or recurring. Recurring obligations support daily, weekly, monthly, or yearly frequencies with flexible scheduling options.' },
  { tool: 'get_all_obligations', purpose: 'Retrieve the list of all obligations owned by the current user across all contracts. Returns obligations with their associated contract details, instances, priority, status, and category. Supports sorting by due date.' },
  { tool: 'get_contract', purpose: 'Retrieve the complete details of a single contract identified by its contract API name. The response includes the contract type, counterparty, owner, primary contact, term and renewal settings, time zone, document links, and the list of amendments with the current stage of each.' },
  { tool: 'get_contract_activity', purpose: 'Retrieve the activity log for a specific contract. Returns a chronological list of all actions performed on the contract, including creation, status changes, modifications, approvals, negotiations, signatures, and other user interactions. Each activity entry includes the action performed, the user who performed it (if applicable), and the timestamp.' },
  { tool: 'get_contract_content', purpose: 'Retrieve the clauses, intro and ending text, and contract field values associated with a specific amendment of a contract. If amendmentId is not provided, returns the current amendment.' },
  { tool: 'get_contract_document_content', purpose: 'Retrieve the rendered text of the latest amendment of a contract\'s document in Markdown or HTML.' },
  { tool: 'get_contract_document_fields', purpose: 'Retrieve the document template fields and their current values for a contract. The response is an array of document field values, separate from the contract form fields and clauses.' },
  { tool: 'get_contract_obligations', purpose: 'Retrieve the list of obligations associated with a specific contract. Returns both one-time and recurring obligations with their current status, task owners, instances, priority, and category information.' },
  { tool: 'get_contract_type_fields', purpose: 'Retrieve the field metadata for a specific contract type template, including system and custom fields, input metadata, data types, display controls, and document-field instances.' },
  { tool: 'get_counterparty', purpose: 'Retrieve the details of a single counterparty identified by its organizationApiName, including its type, status, location, jurisdiction, and contacts.' },
  { tool: 'get_pending_obligations', purpose: 'Retrieve the list of all pending obligations owned by the current user across all contracts. Returns only obligations with instance status of Not Started (11) or In Progress (12), filtering out completed obligations. Includes contract details, instances, priority, status, and category. Supports sorting by due date.' },
  { tool: 'get_report', purpose: 'Retrieve a Zoho Contracts report. Depending on the requested type, this returns the list of active, terminated, or expired contracts, aggregated contract value, the gain or loss from terminated contracts, or obligations grouped by counterparty or status.' },
  { tool: 'get_user_organizations', purpose: 'Retrieve the authenticated user\'s organizations, user details, and default organization domain. This request is not organization-scoped and requires no organization parameter.' },
  { tool: 'list_active_users', purpose: 'Retrieve active users in the current Zoho Contracts organization, optionally filtered by one or more user roles.' },
  { tool: 'list_all_frequent_contract_users', purpose: 'Retrieve the users most frequently assigned a specific contract role across contracts with all counterparties in the organization. Unlike the counterparty-scoped endpoint, this returns frequent users organization-wide.' },
  { tool: 'list_contract_types', purpose: 'Retrieve contract types in the current Zoho Contracts organization, including their API names, publication states, categories, and contracting parties.' },
  { tool: 'list_counterparty_contracts', purpose: 'Retrieve the contracts executed with a specific counterparty. The counterparty is identified by its API name, and the results can be filtered by contract lifecycle status. Only the contracts accessible to the authenticated user are returned.' },
  { tool: 'list_counterparty_types', purpose: 'Retrieve the counterparty types maintained in the organization\'s Choice Lists, including each type\'s API name, display name, and unique identifier.' },
  { tool: 'list_counterparty_users', purpose: 'Retrieve the list of users, also called contacts, belonging to a specific counterparty. The counterparty is identified by its organizationApiName, and the results can be limited to active contacts only.' },
  { tool: 'list_departments', purpose: 'Retrieve departments in the current Zoho Contracts organization, including their API names and display names.' },
  { tool: 'list_frequent_contract_users', purpose: 'Retrieve the users most frequently assigned a specific contract role, such as negotiator or signer, across contracts with the given counterparty.' },
  { tool: 'list_requesters', purpose: 'Retrieve requester names in the current Zoho Contracts organization.' },
  { tool: 'search_all_active_contracts', purpose: 'Retrieve all active contracts from across the entire organization. Active contracts are those currently in force and within their effective term. Available to Admin and Account Owner roles only.' },
  { tool: 'search_all_contracts', purpose: 'Retrieve contracts from across the entire organization. Narrow the results with a free-text search and with filters such as status, contract type, counterparty, owner, requester, department, renewability, and effective, created, or modified date ranges. This endpoint is available only to users with the Admin or Account Owner role.' },
  { tool: 'search_all_inprogress_contracts', purpose: 'Retrieve all in-progress contracts from across the entire organization. In-progress contracts are those in any status from Draft through to before Active. Available to Admin and Account Owner roles only.' },
  { tool: 'search_contracts', purpose: 'Retrieve contracts accessible to the current user. This endpoint returns contracts owned by the user, contracts where they are a team member, and contracts they have permission to view. Available to users with Admin, Account Owner, or Contract Owner roles.' },
  { tool: 'search_counterparties', purpose: 'Search for counterparties by name, or retrieve the full list of counterparties in the organization. Narrow the results using optional filters such as name, counterparty type, region, and the user or date the counterparty was last modified.' },
  { tool: 'search_my_active_contracts', purpose: 'Retrieve active contracts accessible to the current user. Active contracts are those currently in force and within their effective term. Available to Admin, Account Owner, and Contract Owner roles.' },
  { tool: 'search_my_inprogress_contracts', purpose: 'Retrieve in-progress contracts accessible to the current user. In-progress contracts are those in any status from Draft through to before Active. Available to Admin, Account Owner, and Contract Owner roles.' },
  { tool: 'search_obligation_contracts', purpose: 'Retrieve contracts that have obligations assigned to the current user. This returns contracts where the user is a task owner for one or more obligations, regardless of whether they own the contract itself. Available to all roles including Members.' },
  { tool: 'search_shared_contracts', purpose: 'Retrieve contracts that have been explicitly shared with the current user. This returns contracts where the user is not the owner but has been granted access through sharing permissions. Available to all roles including Members.' },
  { tool: 'transfer_contract_ownership', purpose: 'Transfer one or more contracts to new owners by contract API name and owner email.' },
  { tool: 'update_obligation_status', purpose: 'Update the status of an obligation instance. This can be used to mark tasks as Not Started, In Progress, or Completed. For recurring obligations, specify the instanceId to update a specific task instance.' },
];

